-- Installed TW MasterData SHA-256: 730d2aea3e7138d0212b64d80d7fe13e2c72ff03086944f3c8d2e325b4b592cc
-- Append Sanctuary state/configuration; existing saves and migrations are preserved.
CREATE TABLE public.player_dungeon2_runs (
    player_id TEXT PRIMARY KEY REFERENCES public.players(player_id) ON DELETE CASCADE,
    dungeon_code BIGINT NOT NULL,
    week_number INTEGER NOT NULL,
    generation INTEGER NOT NULL DEFAULT 0,
    total_score BIGINT NOT NULL DEFAULT 0 CHECK (total_score >= 0),
    state JSONB NOT NULL,
    checked_at BIGINT NOT NULL
);
CREATE TABLE public.player_dungeon2_records (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    dungeon_group_code BIGINT NOT NULL,
    highest_score BIGINT NOT NULL DEFAULT 0 CHECK (highest_score >= 0),
    PRIMARY KEY(player_id,dungeon_group_code)
);
CREATE TABLE public.player_dungeon2_reward_receipts (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    week_number INTEGER NOT NULL,
    dungeon_code BIGINT NOT NULL,
    hierarchy_index INTEGER NOT NULL,
    received_at BIGINT NOT NULL,
    PRIMARY KEY(player_id,week_number,dungeon_code,hierarchy_index)
);
