INSERT INTO public.game_time_definitions(name,data) VALUES ('dungeon2_story_script_master',$master$[{"Dungeon2SquareCode":600001000,"Title":"學校餐廳","Text":"你誤入了沉眠在聖域中的記憶。\n眼前是學校餐廳。\n餐桌上擺著一個紅通通的蘋果。\n探索這裡，說不定能找到其他糧食。","SoundCode":3000,"BackgroundCode":"1","Options":[{"SelectText":"食用蘋果\n<color=red>回復全體夥伴{0}%的HP</color>","ResultText":"啃咬擺在餐桌上的蘋果。\n清爽的甜味和酸味在嘴裡瀰漫開來。\n\n<color=red>【效果】\n回復全體夥伴25%的HP</color>","ResultText2":"","RewardType":3,"RewardValue":250,"RewardType2":0,"RewardValue2":0,"SuccessRate":{"Percent":100.0,"DecimalDigitCount":0}},{"SelectText":"為尋找糧食進行探索\n<color=red>回復全體夥伴{0}%的HP\n（成功機率{1}%）</color>","ResultText":"廚房深處放置著各式各樣的糧食。\n你填飽肚子後不可思議地湧現了力氣，得以繼續前進。\n\n<color=red>【效果】\n（成功）回復全體夥伴100%的HP</color>","ResultText2":"你走遍學校餐廳各個角落，但沒找到什麼有用的東西。\n只好飢腸轆轆地再次踏出步伐。\n\n<color=red>【效果】\n（失敗）沒有效果</color>","RewardType":3,"RewardValue":1000,"RewardType2":0,"RewardValue2":0,"SuccessRate":{"Percent":50.0,"DecimalDigitCount":0}}]},{"Dungeon2SquareCode":600001010,"Title":"盜賊的祕密據點","Text":"你誤入了沉眠在聖域中的記憶。\n這裡似乎是盜賊的祕密據點，但沒有最近使用過的痕跡。\n此處杳無人煙，感覺可以放心休息。","SoundCode":3000,"BackgroundCode":"1","Options":[{"SelectText":"稍作休息\n<color=red>回復全體夥伴{0}%的HP</color>","ResultText":"此處安靜又陰暗，是個適合休息的地點。\n你在此稍微喘口氣，接著便往出口踏出步伐。\n\n<color=red>【效果】\n回復全體夥伴25%的HP</color>","ResultText2":"","RewardType":3,"RewardValue":250,"RewardType2":0,"RewardValue2":0,"SuccessRate":{"Percent":100.0,"DecimalDigitCount":0}},{"SelectText":"徹底調查祕密據點\n<color=red>給予全體夥伴HP{0}%的傷害\n選擇一個古代的記憶並獲得</color>","ResultText":"不休息就直接調查祕密據點內部。\n雖然中了好幾個陷阱，但成功發現了遺留在深處的財寶。\n\n<color=red>【效果】\n給予全體夥伴HP25%的傷害\n選擇一個古代的記憶並獲得</color>","ResultText2":"","RewardType":7,"RewardValue":250,"RewardType2":6,"RewardValue2":0,"SuccessRate":{"Percent":100.0,"DecimalDigitCount":0}}]},{"Dungeon2SquareCode":600001020,"Title":"美麗的湧泉","Text":"你誤入了沉眠在聖域中的記憶。\n在一片寂靜之中，有座美麗的湧泉。\n你望著泉水，水面上倒映出自己疲憊的臉龐。","SoundCode":3000,"BackgroundCode":"1","Options":[{"SelectText":"飲用泉水\n<color=red>回復全體夥伴{0}%的HP</color>","ResultText":"你正好感到口渴，於是掬起泉水喝下。\n雖然只喝了一點點，但感覺力量湧了出來。\n\n<color=red>【效果】\n回復全體夥伴25%的HP</color>","ResultText2":"","RewardType":3,"RewardValue":250,"RewardType2":0,"RewardValue2":0,"SuccessRate":{"Percent":100.0,"DecimalDigitCount":0}},{"SelectText":"用泉水洗冷水澡\n<color=red>選擇一個古代的記憶並獲得\n（成功機率{0}%）</color>","ResultText":"你決定洗個冷水澡。\n就在此時，你在水中發現了發光的物體。\n要是沒有進入泉水中，應該不會發現到吧。\n\n<color=red>【效果】\n（成功）選擇一個古代的記憶並獲得</color>","ResultText2":"你決定洗個冷水澡。\n泉水相當冷冽，正好可以讓運轉過頭的思緒冷卻下來。\n\n<color=red>【效果】\n（失敗）沒有效果</color>","RewardType":6,"RewardValue":0,"RewardType2":0,"RewardValue2":0,"SuccessRate":{"Percent":50.0,"DecimalDigitCount":0}}]}]$master$::jsonb) ON CONFLICT(name) DO UPDATE SET data=EXCLUDED.data;
